OPS = {"+": lambda a, b: a + b, "-": lambda a, b: a - b,
       "*": lambda a, b: a * b, "^": lambda a, b: a ** b}

def evaluate(node):
    if isinstance(node, (int, float)):
        return node
    op, left, right = node
    return OPS[op](evaluate(left), evaluate(right))

def show(node):
    if isinstance(node, (int, float)):
        return str(node)
    op, left, right = node
    return f"({show(left)} {op} {show(right)})"

